                _ = bun.destroy(self);
            } else {
                _ = uv.uv_fs_event_stop((&self.handle));
                _ = uv.uv_close(@ptrCast((&self.handle)), PathWatcher.uvClosedCallback);
            }
    }
    pub const new = bun.TrivialNew(PathWatcher);
    const log = Output.scoped(.@"fs.watch", .visible);
    pub const Callback = PathWatcherCallback;
    pub const UpdateEndCallback = PathWatcherUpdateEndCallback;
};

const string = []const u8;
pub const PathWatcherCallback = *const fn (?*void, Event, bool) void;
pub const PathWatcherUpdateEndCallback = *const fn (?*void) void;
const Output = bun.Output;
const Watcher = bun.Watcher;
const jsc = bun.jsc;
const VirtualMachine = jsc.VirtualMachine;
const FSWatcher = bun.jsc.Node.fs.Watcher;
const Event = FSWatcher.Event;
const onPathUpdateFn = jsc.Node.fs.Watcher.onPathUpdate;
const onUpdateEndFn = jsc.Node.fs.Watcher.onUpdateEnd;
const windows = bun.windows;
const uv = windows.libuv;
const EventType = path_watcher.PathWatcher.EventType;
var default_manager: ?*PathWatcherManager = null;

pub fn watch(vm: *VirtualMachine, path: [:0]const u8, recursive: bool, comptime callback: PathWatcher.Callback, comptime updateEnd: PathWatcher.UpdateEndCallback, ctx: *void) bun.sys.Maybe(*PathWatcher) {
        comptime {
        if ((callback != onPathUpdateFn)) {
            _ = @compileError("callback must be onPathUpdateFn");
        }
        if ((updateEnd != onUpdateEndFn)) {
            _ = @compileError("updateEnd must be onUpdateEndFn");
        }

}
        if ((!bun.Environment.isWindows)) {
            _ = @compileError("win_watcher should only be used on Windows");
        }
        var manager = default_manager;
        _ = &manager;
        if ((manager == null)) {
            default_manager = PathWatcherManager.init(vm);
            manager = default_manager;
        }
        const mgr = manager.?;
        var watcher = (switch (PathWatcher.init(mgr, path, recursive)) {
.err => |e| {
return .{ .err = e };
},
.result => |w| w,
});
        _ = &watcher;
        _ = bun.handleOom(watcher.handlers.put(bun.default_allocator, ctx, .{}));
        return .{ .result = watcher };
}
